//! Device capability claims cannot drift from code or outrun their evidence (#788).
//!
//! The provider matrix in AGENTS.md is generated by `tests/mcp_contract.rs`. Devices get the same
//! treatment: the device table is rendered from `capabilities_for`, the function the adapter
//! itself publishes, and a `hardware-verified` claim must point at a fixture directory that exists.
//!
//! Regenerate the table with:
//!
//! ```sh
//! UPDATE_AGENTS_DEVICES=1 cargo test --test device_claims
//! ```

use std::path::Path;

use unified_hifi_control::adapters::denonavr::{
    capabilities_for, READ_VERIFIED_MODELS, WRITE_VERIFIED_MODELS,
};
use unified_hifi_control::devices::{CapabilityEvidence, DeviceCapability};

const BEGIN: &str = "<!-- BEGIN GENERATED DEVICE CAPABILITIES (tests/device_claims.rs) -->";
const END: &str = "<!-- END GENERATED DEVICE CAPABILITIES -->";

fn cell(capability: &DeviceCapability) -> String {
    match (capability.supported, capability.evidence) {
        (false, _) => "⛔".to_string(),
        (true, CapabilityEvidence::HardwareVerified) => "✅ hardware-verified".to_string(),
        (true, CapabilityEvidence::ImplementationDerived) => "🚧 implemented, #788".to_string(),
    }
}

fn row(label: &str, claims: &unified_hifi_control::devices::DeviceCapabilities) -> String {
    format!(
        "| {label} | {} | {} | {} | {} | {} |\n",
        cell(&claims.observe),
        cell(&claims.volume),
        cell(&claims.mute),
        cell(&claims.power),
        cell(&claims.input_select),
    )
}

/// Every family's claims, from the same functions the adapters publish.
fn family_rows() -> Vec<(String, unified_hifi_control::devices::DeviceCapabilities)> {
    use unified_hifi_control::adapters::*;
    let mut rows = Vec::new();
    for (model, _) in READ_VERIFIED_MODELS {
        rows.push((format!("Marantz {model}"), capabilities_for(model)));
    }
    rows.push((
        "Other Denon / Marantz".to_string(),
        capabilities_for("(other)"),
    ));
    for (model, _) in wiim::READ_VERIFIED_MODELS {
        rows.push(((*model).to_string(), wiim::capabilities_for(model)));
    }
    rows.push((
        "Other WiiM / LinkPlay".to_string(),
        wiim::capabilities_for("WiiM"),
    ));
    rows.push(("Sonos".to_string(), sonos::capabilities_for("Sonos", false)));
    rows.push((
        "Yamaha MusicCast".to_string(),
        // A main zone advertising the usual func_list, as getFeatures reports for a receiver.
        musiccast::capabilities_for(
            "MusicCast",
            &musiccast::protocol::parse_features(
                r#"{"response_code":0,"zone":[{"id":"main","func_list":["power","volume","mute"],
                    "range_step":[{"id":"volume","min":0,"max":161,"step":1}],
                    "input_list":["hdmi1","net_radio"]}]}"#,
            )
            .expect("representative getFeatures"),
        ),
    ));
    rows.push((
        "BluOS".to_string(),
        bluos::capabilities_for("BluOS", bluos::protocol::VolumeSupport::Variable, true),
    ));
    rows.push((
        "Cambridge StreamMagic (variable output)".to_string(),
        streammagic::capabilities_for("StreamMagic", true),
    ));
    rows.push((
        "Trinnov Altitude (MAC configured)".to_string(),
        trinnov::capabilities_for("Altitude", true),
    ));
    rows.push((
        "Onkyo / Integra / Pioneer (eISCP)".to_string(),
        eiscp::capabilities_for("eISCP"),
    ));
    rows.push(("Arcam".to_string(), arcam::capabilities_for("SA30")));
    rows.push(("Hegel".to_string(), hegel::capabilities_for("H190")));
    rows.push(("Lyngdorf".to_string(), lyngdorf::capabilities_for("MP-60")));
    rows.push(("Anthem".to_string(), anthem::capabilities_for("MRX 540")));
    rows.push((
        "Eversolo DMP-A6".to_string(),
        eversolo::capabilities_for("DMP-A6", true, true),
    ));
    rows.push((
        "Home Assistant media_player".to_string(),
        homeassistant_devices::protocol::capabilities(4 | 8 | 128 | 256 | 2048),
    ));
    rows
}

fn render() -> String {
    let mut out = String::new();
    out.push_str(BEGIN);
    out.push_str("\n\n");
    out.push_str(
        "| Family | Observe | Volume | Mute | Power | Input select |\n|---|---|---|---|---|---|\n",
    );
    for (label, claims) in family_rows() {
        out.push_str(&row(&label, &claims));
    }
    out.push_str(
        "\n✅ hardware-verified: exercised on real units with captured fixtures · 🚧 implemented \
         from the vendor protocol or reference client, not exercised on hardware (#788) · ⛔ not \
         supported by this family's protocol path\n\n",
    );
    for (label, claims) in family_rows() {
        out.push_str(&format!(
            "- **{label}** — volume: {}; power: {}\n",
            claims.volume.detail, claims.power.detail
        ));
    }
    out.push('\n');
    out.push_str(END);
    out
}

/// No family other than a hardware-captured one may claim hardware verification.
#[test]
fn only_captured_models_claim_hardware_verification() {
    for (label, claims) in family_rows() {
        let captured = label.starts_with("Marantz SR6008")
            || unified_hifi_control::adapters::wiim::READ_VERIFIED_MODELS
                .iter()
                .any(|(model, _)| *model == label);
        if captured {
            continue;
        }
        for claim in [
            &claims.observe,
            &claims.volume,
            &claims.mute,
            &claims.power,
            &claims.input_select,
        ] {
            assert_eq!(
                claim.evidence,
                CapabilityEvidence::ImplementationDerived,
                "{label}: {}",
                claim.detail
            );
        }
    }
}

/// A `hardware-verified` claim must name a fixture directory that exists and documents itself.
#[test]
fn hardware_verified_claims_point_at_existing_captures() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    use unified_hifi_control::adapters::wiim;
    for (model, directory) in READ_VERIFIED_MODELS
        .iter()
        .chain(WRITE_VERIFIED_MODELS)
        .chain(wiim::READ_VERIFIED_MODELS)
        .chain(wiim::WRITE_VERIFIED_MODELS)
    {
        let directory = root.join(directory);
        assert!(
            directory.join("README.md").is_file(),
            "{model} is claimed hardware-verified, but {} has no README describing the capture",
            directory.display()
        );
        let captures = std::fs::read_dir(&directory)
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| entry.file_name() != "README.md")
            .count();
        assert!(captures > 0, "{model}: no captures beside the README");
    }
}

/// Until a write capture exists, no write path may claim hardware verification — the catalog's
/// rule: implementation- or source-derived support never becomes a hardware-tested claim.
#[test]
fn write_claims_are_not_hardware_verified_without_a_write_capture() {
    for (model, _) in READ_VERIFIED_MODELS {
        if WRITE_VERIFIED_MODELS.iter().any(|(m, _)| m == model) {
            continue;
        }
        let claims = capabilities_for(model);
        for claim in [
            &claims.volume,
            &claims.mute,
            &claims.power,
            &claims.input_select,
        ] {
            assert_eq!(
                claim.evidence,
                CapabilityEvidence::ImplementationDerived,
                "{model}: {}",
                claim.detail
            );
        }
    }
}

/// A unit reached over HTTP only (no MVMAX) still has volume: the protocol's full scale bounds it.
#[test]
fn volume_is_advertised_without_mvmax() {
    assert!(capabilities_for("SR6008").volume.supported);
}

#[test]
fn agents_md_device_table_matches_the_derived_claims() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("AGENTS.md");
    let agents = std::fs::read_to_string(&path).unwrap();
    let start = agents
        .find(BEGIN)
        .expect("AGENTS.md has no generated device table");
    let end = agents
        .find(END)
        .expect("generated device table is unterminated")
        + END.len();
    let rendered = render();
    if agents[start..end] != rendered {
        if std::env::var("UPDATE_AGENTS_DEVICES").as_deref() == Ok("1") {
            let updated = format!("{}{}{}", &agents[..start], rendered, &agents[end..]);
            std::fs::write(&path, updated).unwrap();
            return;
        }
        panic!(
            "AGENTS.md device table is stale. Regenerate with \
             UPDATE_AGENTS_DEVICES=1 cargo test --test device_claims\n\nexpected:\n{rendered}"
        );
    }
}
